						this.tablePage.totalResult = res.count
						this.loading = false
							
							
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				//}
			   
			},
			toggleExpandMethod ({ expanded, row }) {
				  if (expanded) {
				 console.log(row.产品ID)
				 let tj = '产品ID' + "=" +  '"' + row.产品ID + '"';
				 let tjy = `库存数量 > 0`
				 Query({
							tj:tj + ' and ' + tjy,
							tablename:'查询库存',
							field:'id'
						})
						.then(res => {
						let cpsj = this.cplist
					    let ssy = res.data.map(function(v,i) {
						let obj5 = cpsj.find(o => o.产品ID === v.产品ID); 
						delete obj5.id;
						delete obj5.日期;
						 return   Object.assign(v,obj5);						
						});	
						console.log(ssy)
							this.childData = ssy							 							
						})
						.catch(err => {
							// 异常情况
							
						})
				  }
              return true
            }, 
			checkDev() {
				this.isDev = (process.env.NODE_ENV === 'development') ? true : false
			},
			changePassword() {
				this.$prompt('请输入新密码：', '提示', {
					confirmButtonText: '确定',
					cancelButtonText: '取消',
					inputPattern: /^[a-zA-Z]\w{5,17}$/,
					inputErrorMessage: '以字母开头，长度在6~18之间，只能包含字母、数字和下划线'
				}).then(({
					value
				}) => {
					UpdateUserPassword({
							ID: this.$util.cookies.get('uuid'),
							Password: this.$md5(value)
						})
						.then(res => {
							this.$message.success('密码修改成功')
						})
						.catch(err => {})
				}).catch(() => {});
			},
			handleOpenForm(e) {
				this.$router.push({
					path: '/' + e
				})
			},
			

			handleSearch() {
				if(this.searchFilter.disable !='' && this.searchFilter.disable !=null){
				this.tablePage.currentPage = 1 //注意要回来第一页
				this.getTableData()
				}else{
					this.$message.error('请先选择查询的库存类型')
				}
			},
			handlePageChange({
				currentPage,
				pageSize
			}) {
				this.tablePage.currentPage = currentPage
				this.tablePage.pageSize = pageSize
				this.getTableData()
			},
			clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					this.searchFilter
					obj[key] = null
				}
			},

			exportDataEvent() {
				this.$refs.xTable1.exportData({
					type: 'csv'
				})
			},

			querySearch(queryString, cb) {
				let values = this.disables; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			createFilter(queryString) {
				return (e) => {
					return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
				}
			},
			qinchu() {	
				let obj = this.searchFilter
				obj['disable'] = null
                      
               }
		}
	}
</script>

